39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	const withFirstInsuranceSurcharge = (policyBase: number): number =>
51	  policyBase + policyBase * FIRST_INSURANCE_RATE;
52	
53	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
54	
55	const policyBasePremium = (items: Item[]): number =>
56	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
57	
58	const quotePremium = (items: Item[]): number => {
59	  const policyBase = policyBasePremium(items);
60	  const afterModifiers = withFirstInsuranceSurcharge(policyBase);
61	  return afterModifiers + PROCESSING_FEE;
62	};
63	
64	const runStep = (step: Step): StepResult => {
65	  if (step.op === "quote") return { premium: quotePremium(step.items) };
66	  throw new Error(`unsupported step: ${step.op}`);
67	};
68	
69	export const runScenario = (scenario: Scenario): ScenarioResult => ({
70	  results: scenario.steps.map(runStep),
71	});
